"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[6192],{46192:a=>{a.exports=JSON.parse('{"meta":{"title":"Sukarelawan - iMuslim Life","description":"Bantu umat Islam di seluruh dunia solat tepat pada waktunya dan membaca al-Quran dalam bahasa mereka. Jadi sukarelawan penterjemah, qari, penyemak, penulis, penguji atau duta masjid."},"chip":"Jadi sukarelawan","h1":"Kemahiran anda boleh menjadi sedekah jariah","lede":"Salat-e-Mustaqeem dan iMuslim Life adalah percuma, tanpa iklan, dan digunakan setiap hari oleh umat Islam di seluruh dunia. Beberapa jam masa anda boleh membantu seseorang solat tepat pada waktunya, memahami al-Quran dalam bahasanya, atau mencari masjid terdekat, berulang kali.","heroCta":"E-mel kami untuk menyertai","hadith":{"text":"\u201cSesiapa yang menunjukkan kepada kebaikan, maka baginya pahala seperti orang yang melakukannya.\u201d","source":"Nabi Muhammad sallallahu \u2018alaihi wasallam, Sahih Muslim 1893"},"why":"Setiap perkataan yang anda terjemahkan dibaca oleh orang yang tidak akan anda temui. Setiap bacaan yang anda rakam didengar di rumah, kereta dan masjid. Kami pasukan kecil, dan sukarelawanlah yang membawa usaha ini ke setiap bahasa dan setiap pelosok dunia.","rolesH2":"Cara anda boleh membantu","rolesSub":"Pilih yang sesuai dengan anda. Tiada pengalaman teknikal diperlukan, hanya keikhlasan, ketelitian dan sedikit masa.","roleCta":"Saya boleh bantu","roles":{"translate":{"title":"Penterjemah","text":"Bawa aplikasi, laman web, doa dan kisah mingguan ke dalam bahasa anda: Melayu, Indonesia, Arab, Urdu, Perancis, Sepanyol, Turki, Bengali, Hindi dan banyak lagi. Setiap terjemahan kami semak sebelum diterbitkan.","time":"Dari 1\u20132 jam seminggu"},"recite":{"title":"Qari","text":"Jika Allah mengurniakan anda suara yang merdu dan tajwid yang betul, rakam bacaan al-Quran, doa atau azan untuk pendengar di seluruh dunia. Kami bantu dengan rakaman dan suntingan.","time":"Rakam mengikut masa anda"},"review":{"title":"Ilmuwan dan penyemak","text":"Penuntut ilmu, imam dan guru: semak ketepatan dan sumber terjemahan, kisah dan jawapan kuiz, supaya semua yang kami terbitkan boleh dipercayai.","time":"Semak bila-bila anda mampu"},"write":{"title":"Penulis dan pencerita","text":"Bantu menulis kisah mingguan para Nabi, Sahabat dan Sirah untuk keluarga dan kanak-kanak, dalam bahasa Melayu atau bahasa lain, sentiasa daripada sumber yang sahih.","time":"Satu kisah sebulan sudah sangat membantu"},"test":{"title":"Penguji","text":"Cuba ciri baharu sebelum dilancarkan di iPhone, Android atau Alexa, dan beritahu kami apa yang terasa salah atau mengelirukan. Mata yang segar nampak apa yang kami terlepas.","time":"Beberapa minit setiap keluaran"},"masjid":{"title":"Duta masjid","text":"Bantu masjid tempatan anda menerbitkan waktu iqamah dan solat Jumaat supaya jemaahnya dapat melihatnya dalam aplikasi, laman web dan Alexa. Percuma untuk setiap masjid.","time":"Satu perbualan boleh memberi manfaat kepada seluruh jemaah"}},"stepsH2":"Bagaimana ia berfungsi","steps":{"s1":{"title":"E-mel kami","text":"Beritahu kami peranan yang anda pilih, bahasa yang anda kuasai dan sedikit tentang diri anda."},"s2":{"title":"Kami membalas sendiri","text":"Kami menghubungi anda dengan panduan ringkas dan tugasan kecil pertama."},"s3":{"title":"Hasil kerja anda diterbitkan","text":"Selepas disemak, sumbangan anda sampai kepada orang ramai di seluruh dunia."}},"promiseH2":"Apa yang anda boleh harapkan daripada kami","promise":{"p1":{"title":"Masa anda, rentak anda","text":"Tiada komitmen minimum. Bantu bila mampu, berehat bila perlu."},"p2":{"title":"Nama anda, jika mahu","text":"Kami gembira berterima kasih dengan menyebut nama anda, atau merahsiakan bantuan anda antara anda dan Allah. Pilihan anda."},"p3":{"title":"Teliti dan tepat","text":"Kandungan agama disemak dan diberi sumber sebelum diterbitkan. Anda tidak memikulnya seorang diri."},"p4":{"title":"Privasi anda dihormati","text":"Kami menggunakan e-mel anda hanya untuk bekerja dengan anda, tidak sekali-kali berkongsi atau memasukkannya ke senarai mel."}},"finalH2":"Bersedia untuk membantu?","finalText":"Hantar satu e-mel kepada kami. Walaupun belum pasti di mana anda sesuai, tulislah kepada kami, insya-Allah kita cari tempat yang tepat bersama."}')}}]);